  "risks": [
    {
      "condition": "The proposal must be submitted through the College's procurement portal as a single PDF of no more than 20 pages by 2026-12-01 12:00 UTC under REQ-0001.",
      "event": "The final proposal document exceeds 20 pages or is uploaded after the deadline due to network delays.",
      "effect": "The proposal is rejected without evaluation, disqualifying the bid entirely.",
      "assumptions": ["The buyer manages proposal submission formatting independently."],
      "owner_role": "Bid manager",
      "trigger": "The draft reaches 18 pages or the upload date approaches 2026-11-30.",
      "responses": [
        "Enforce a strict 18-page limit on the draft.",
        "Upload the proposal 24 hours in advance of the deadline."
      ],
      "residual_exposure": "A minor risk of portal downtime on the final day, mitigated by early submission.",
      "evidence_src_ids": ["REQ-0001"],
      "affects": ["REQ-0001"]
    },
    {
      "condition": "The service must be live for students by 2027-01-11 under REQ-0012, while work package 3.1 requires 20 to 40 days and depends on work packages 1.2 and 2.1.",
      "event": "The prerequisite work packages take longer than expected, delaying the spring enrollment go-live past 2027-01-11.",
      "effect": "Students cannot use the required signing service on the first day of spring enrollment, breaching the contract.",
      "assumptions": ["Migration and support requirements are met within the stated partial claims."],
      "owner_role": "Delivery lead",
      "trigger": "Work package 1.2 or 2.1 slips past its estimated low days.",
      "responses": [
        "Prioritize core signing and REST API integration to meet the 2027-01-11 deadline.",
        "De-scope non-mandatory features temporarily to protect the go-live date."
      ],
      "residual_exposure": "Potential delay in secondary features if high-end day estimates for work packages are realized.",
      "evidence_src_ids": ["REQ-0012"],
      "affects": ["REQ-0012"]
    }
  ],
  "open_questions": [
    {
      "text": "Are there specific format or schema details available for the College's existing REST API mentioned in REQ-0008?",
      "src_ids": ["REQ-0008"]
    }
  ]
}

